
    /* ============================================================
       DNA HELIX CANVAS — HERO (Full-background)
       ============================================================ */
    (function () {
      const canvas = document.getElementById('heroCanvas');
      const ctx = canvas.getContext('2d');
      let W, H, mouse = { x: 0.5, y: 0.5 }, targetMX = 0.5, targetMY = 0.5;
      let scrollY = 0, heroH = 0;
      let animId;

      function resize() {
        W = canvas.width = canvas.offsetWidth;
        H = canvas.height = canvas.offsetHeight;
        heroH = canvas.offsetHeight;
      }
      resize();
      window.addEventListener('resize', resize);

      document.addEventListener('mousemove', function (e) {
        targetMX = e.clientX / window.innerWidth;
        targetMY = e.clientY / window.innerHeight;
      });
      window.addEventListener('scroll', function () {
        scrollY = window.scrollY;
      });

      // Particles
      const NUM_PARTICLES = 18;
      const particles = Array.from({ length: NUM_PARTICLES }, () => ({
        x: Math.random() * 1,
        y: Math.random() * 1,
        r: 1.5 + Math.random() * 1.5,
        dx: (Math.random() - 0.5) * 0.0003,
        dy: (Math.random() - 0.5) * 0.0003,
      }));

      let t = 0;

      function draw() {
        ctx.clearRect(0, 0, W, H);

        // Ease mouse parallax
        mouse.x += (targetMX - mouse.x) * 0.04;
        mouse.y += (targetMY - mouse.y) * 0.04;

        const scrollFrac = Math.min(scrollY / (heroH || 800), 1);
        const baseAlpha = 0.07 * (1 - scrollFrac);
        if (baseAlpha <= 0) { animId = requestAnimationFrame(draw); return; }

        const parallaxX = (mouse.x - 0.5) * -30;
        const parallaxY = (mouse.y - 0.5) * -20;
        const scrollDrift = -scrollY * 0.15;

        const cx = W / 2 + parallaxX;
        const cy = H / 2 + parallaxY + scrollDrift;

        // DNA Helix params
        const helixH = Math.min(H * 0.85, 700);
        const helixTop = cy - helixH / 2;
        const helixBot = cy + helixH / 2;
        const RUNGS = 22;
        const AMP = Math.min(W * 0.13, 90);
        const speed = (2 * Math.PI) / (80 * 60); // 80s full rotation at 60fps

        t += speed;

        const tealR = 10, tealG = 107, tealB = 94;
        const tealBase = `rgba(${tealR},${tealG},${tealB},`;

        // Draw connecting rungs (base pairs)
        for (let i = 0; i < RUNGS; i++) {
          const frac = i / (RUNGS - 1);
          const y = helixTop + frac * helixH;
          const angle = t + frac * Math.PI * 6;

          const x1 = cx + Math.cos(angle) * AMP;
          const x2 = cx + Math.cos(angle + Math.PI) * AMP;

          const rungAlpha = baseAlpha * 0.65;
          ctx.beginPath();
          ctx.moveTo(x1, y);
          ctx.lineTo(x2, y);
          ctx.strokeStyle = tealBase + rungAlpha + ')';
          ctx.lineWidth = 1;
          ctx.stroke();

          // Small dots at ends of rungs
          const dotR = 2.5;
          [x1, x2].forEach(function (x) {
            ctx.beginPath();
            ctx.arc(x, y, dotR, 0, Math.PI * 2);
            ctx.fillStyle = tealBase + (baseAlpha * 1.3) + ')';
            ctx.fill();
          });
        }

        // Draw two helical strands
        for (let strand = 0; strand < 2; strand++) {
          const phaseOffset = strand === 0 ? 0 : Math.PI;
          ctx.beginPath();
          let first = true;
          const STEPS = 120;
          for (let s = 0; s <= STEPS; s++) {
            const frac = s / STEPS;
            const y = helixTop + frac * helixH;
            const angle = t + frac * Math.PI * 6 + phaseOffset;
            const x = cx + Math.cos(angle) * AMP;
            if (first) { ctx.moveTo(x, y); first = false; }
            else ctx.lineTo(x, y);
          }
          ctx.strokeStyle = tealBase + baseAlpha + ')';
          ctx.lineWidth = 1.5;
          ctx.stroke();
        }

        // Draw floating particles
        for (let i = 0; i < NUM_PARTICLES; i++) {
          const p = particles[i];
          p.x += p.dx; p.y += p.dy;
          if (p.x < 0 || p.x > 1) p.dx *= -1;
          if (p.y < 0 || p.y > 1) p.dy *= -1;
          ctx.beginPath();
          ctx.arc(p.x * W, p.y * H, p.r, 0, Math.PI * 2);
          ctx.fillStyle = tealBase + (baseAlpha * 0.8) + ')';
          ctx.fill();
        }

        animId = requestAnimationFrame(draw);
      }

      draw();
    })();

