    /* ============================================================
       HAMBURGER / MOBILE MENU
       ============================================================ */
    (function () {
      const btn = document.getElementById('hamburgerBtn');
      const menu = document.getElementById('mobileMenu');
      const close = document.getElementById('mobileClose');
      
      function open() { 
        menu.classList.add('open'); 
        btn.setAttribute('aria-expanded', 'true'); 
        btn.classList.add('active');
      }
      
      function shut() { 
        menu.classList.remove('open'); 
        btn.setAttribute('aria-expanded', 'false'); 
        btn.classList.remove('active');
      }
      
      if (btn && menu) {
        btn.addEventListener('click', function (e) {
          e.stopPropagation();
          if (menu.classList.contains('open')) {
            shut();
          } else {
            open();
          }
        });
      }
      
      if (close) {
        close.addEventListener('click', shut);
      }
      
      menu.querySelectorAll('a.mobile-link').forEach(function (a) { 
        a.addEventListener('click', shut); 
      });
      
      // Close menu and open modal smoothly when mobile invite button is clicked
      const mobileInviteBtn = document.getElementById('mobileInviteBtn');
      if (mobileInviteBtn) {
        mobileInviteBtn.addEventListener('click', function () {
          shut();
        });
      }
    })();

