    // Store original inner HTML of modal boxes so we can reset them when closed
    const modalOriginals = {};
    
    // Helper to cache original contents
    window.addEventListener('DOMContentLoaded', function() {
      document.querySelectorAll('.modal-overlay').forEach(function (o) {
        const box = o.querySelector('.modal-box');
        if (box) {
          modalOriginals[o.id] = box.innerHTML;
        }
      });
    });

    function openModal(id) {
      document.getElementById(id).classList.add('open');
      document.body.style.overflow = 'hidden';
    }
    
    function closeModal(id) {
      document.getElementById(id).classList.remove('open');
      document.body.style.overflow = '';
      
      // Reset the modal content to show the form again on next open
      setTimeout(function() {
        const o = document.getElementById(id);
        const box = o ? o.querySelector('.modal-box') : null;
        if (box && modalOriginals[id]) {
          box.innerHTML = modalOriginals[id];
          if (id === 'delegateModal') {
            bindDelegateForm();
          } else if (id === 'sponsorModal') {
            bindSponsorForm();
          }
        }
      }, 350); // Match transition duration (0.35s / 0.3s)
    }

    // Function to bind Delegate Form events and AJAX submission
    function bindDelegateForm() {
      var delegateForm = document.getElementById('delegateForm');
      if (!delegateForm) return;

      var roleSelect = document.getElementById('d-role');
      var subjectInput = delegateForm.querySelector('input[name="_subject"]');
      if (roleSelect && subjectInput) {
        roleSelect.addEventListener('change', function () {
          subjectInput.value = 'Pharma Vista 2026 — ' + roleSelect.value + ' Application';
        });
      }

      var delegateFormStarted = false;
      delegateForm.querySelectorAll('input, select, textarea').forEach(function (el) {
        el.addEventListener('focus', function () {
          if (!delegateFormStarted) {
            delegateFormStarted = true;
            gtag('event', 'form_start', { 'form_id': 'delegateForm' });
          }
        });
      });

      delegateForm.addEventListener('submit', function (e) {
        e.preventDefault();
        gtag('event', 'form_submit', { 'form_id': 'delegateForm' });

        const submitBtn = delegateForm.querySelector('.form-submit');
        const originalText = submitBtn.textContent;
        submitBtn.textContent = 'Sending...';
        submitBtn.disabled = true;

        const formData = new FormData(delegateForm);
        const data = {};
        formData.forEach((value, key) => {
          // Send all fields except hidden honey/redirect configs which formsubmit handles on direct POST
          if (!key.startsWith('_')) {
            data[key] = value;
          }
        });

        // Use FormSubmit AJAX endpoint
        fetch('https://formsubmit.co/ajax/delegates@pharmavistaglobal.com', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
          },
          body: JSON.stringify(data)
        })
        .then(response => response.json())
        .then(resData => {
          gtag('event', 'form_submit_success', { 'form_id': 'delegateForm' });
          window.location.href = 'thank-you.html';
        })
        .catch(error => {
          console.error('Error submitting delegate form:', error);
          submitBtn.textContent = originalText;
          submitBtn.disabled = false;
          alert('Something went wrong. Please try again or contact delegates@pharmavistaglobal.com.');
        });
      });
    }

