    /* ============================================================
       PREMIUM CUSTOM CURSOR EFFECT
       ============================================================ */
    (function () {
      // Check if touch device based on touch events support or pointer capabilities
      const isTouchDevice = ('ontouchstart' in window) || (navigator.maxTouchPoints > 0) || (navigator.msMaxTouchPoints > 0);

      if (isTouchDevice) {
        return; // Revert to default cursor on touch devices to preserve usability/battery
      }

      // Create custom cursor elements dynamically to keep markup clean
      const cursorGroup = document.createElement('div');
      cursorGroup.className = 'custom-cursor-group';
      cursorGroup.id = 'customCursorGroup';

      const cursorDot = document.createElement('div');
      cursorDot.className = 'cursor-dot';
      cursorDot.id = 'cursorDot';

      const cursorDotInner = document.createElement('div');
      cursorDotInner.className = 'cursor-dot-inner';
      cursorDot.appendChild(cursorDotInner);

      const cursorOutline = document.createElement('div');
      cursorOutline.className = 'cursor-outline';
      cursorOutline.id = 'cursorOutline';

      const cursorOutlineInner = document.createElement('div');
      cursorOutlineInner.className = 'cursor-outline-inner';

      cursorOutline.appendChild(cursorOutlineInner);
      cursorGroup.appendChild(cursorDot);
      cursorGroup.appendChild(cursorOutline);
      document.body.appendChild(cursorGroup);

      // Activate custom cursor styling on the body
      document.body.classList.add('custom-cursor-active');

      // Track cursor position coordinates
      let mouseX = 0, mouseY = 0;
      let outlineX = 0, outlineY = 0;
      let hasMoved = false;

      // Listen to mouse movement
      document.addEventListener('mousemove', function (e) {
        mouseX = e.clientX;
        mouseY = e.clientY;

        if (!hasMoved) {
          hasMoved = true;
          cursorGroup.classList.add('visible');
          // Set initial positions immediately so it doesn't animate from (0,0)
          outlineX = mouseX;
          outlineY = mouseY;
        }

        // Dot follows mouse instantly (centered by subtracting half-width 8px)
        cursorDot.style.transform = 'translate3d(' + (mouseX - 8) + 'px, ' + (mouseY - 8) + 'px, 0)';
      });

      // Lerp factor for smooth, premium delayed lag on outline
      const lerpFactor = 0.15;
      function lerp(start, end, amt) {
        return (1 - amt) * start + amt * end;
      }

      // Animation loop using requestAnimationFrame for smooth 60fps+ rendering
      function updateCursor() {
        if (hasMoved) {
          // Outline follows mouse with linear interpolation
          outlineX = lerp(outlineX, mouseX, lerpFactor);
          outlineY = lerp(outlineY, mouseY, lerpFactor);
          // Outline follows mouse with offset (centered by subtracting half-width 20px)
          cursorOutline.style.transform = 'translate3d(' + (outlineX - 20) + 'px, ' + (outlineY - 20) + 'px, 0)';
        }
        requestAnimationFrame(updateCursor);
      }
      requestAnimationFrame(updateCursor);

      // Interactive element selectors
      const hoverSelector = 'a, button, [data-cursor="hover"], .theme-card, .pillar-card, .hl-card, .aud-card';

      // Large hero typography selectors for color inversion effect
      const blendSelector = 'h1, h2, .hero-title, .section-title, .cine-main-title, .cta-title';

      // Usability selector: Hide custom cursor on text inputs to prevent overlapping cursors
      const inputSelector = 'input, select, textarea';

      // Hover states using event delegation (high performance, dynamic-element friendly)
      document.addEventListener('mouseover', function (e) {
        // Interactive element hovers
        const hoverEl = e.target.closest(hoverSelector);
        if (hoverEl) {
          cursorOutline.classList.add('hovered');
          cursorDot.classList.add('hovered');
        }

        // Inversion blend mode hovers (h1, h2, etc.)
        const blendEl = e.target.closest(blendSelector);
        if (blendEl) {
          cursorGroup.classList.add('blend-mode-difference');
        }

        // Form inputs: Hide custom cursor dynamically to restore native cursor usability
        if (e.target.closest(inputSelector)) {
          cursorGroup.classList.remove('visible');
        }
      });

      document.addEventListener('mouseout', function (e) {
        // Interactive element hover release
        const hoverEl = e.target.closest(hoverSelector);
        if (hoverEl) {
          if (!e.relatedTarget || !e.relatedTarget.closest(hoverSelector)) {
            cursorOutline.classList.remove('hovered');
            cursorDot.classList.remove('hovered');
          }
        }

        // Inversion blend mode hover release
        const blendEl = e.target.closest(blendSelector);
        if (blendEl) {
          if (!e.relatedTarget || !e.relatedTarget.closest(blendSelector)) {
            cursorGroup.classList.remove('blend-mode-difference');
          }
        }

        // Form inputs hover release: restore custom cursor visibility
        if (e.target.closest(inputSelector)) {
          if (!e.relatedTarget || !e.relatedTarget.closest(inputSelector)) {
            cursorGroup.classList.add('visible');
          }
        }
      });

      // Click animation: scale down outline on mousedown, spring back on mouseup
      document.addEventListener('mousedown', function () {
        cursorOutline.classList.add('clicked');
      });

      document.addEventListener('mouseup', function () {
        cursorOutline.classList.remove('clicked');
      });

      // Handle cursor visibility when mouse leaves / enters viewport
      document.addEventListener('mouseleave', function () {
        cursorGroup.classList.remove('visible');
      });

      document.addEventListener('mouseenter', function () {
        if (hasMoved) {
          cursorGroup.classList.add('visible');
        }
      });
    })();

    /* ============================================================
       INTERACTIVE 3D PARTICLE GLOBE — HERO SECTION MOUSE-REVEAL
       ============================================================ */
    (function () {
      const hero = document.getElementById('hero');
      const canvas = document.getElementById('constellationCanvas');
      if (!hero || !canvas) return;

      const ctx = canvas.getContext('2d');
      let width, height;

      function resize() {
        width = canvas.width = hero.offsetWidth;
        height = canvas.height = hero.offsetHeight;
      }
      resize();
      window.addEventListener('resize', resize);

      const particles = [];

      // Configuration
      const NUM_RINGS = 24;
      const MAX_PARTICLES_PER_RING = 48;
      const FOCAL_LENGTH = 400;

      // Mouse state for spotlight reveal
      let mouseX = -9999, mouseY = -9999;
      let smoothMouseX = -9999, smoothMouseY = -9999;
      let mouseActive = false;
      const REVEAL_RADIUS = 450; // Large spotlight circle radius
      const MOUSE_LERP = 0.12;

      // Rotation state
      let angleY = 0;
      const spinSpeed = 0.0015;

      // Tilt offsets
      const DEFAULT_TILT_X = 0.22;
      const DEFAULT_TILT_Y = 0.0;
      let currentTiltX = DEFAULT_TILT_X;
      let currentTiltY = DEFAULT_TILT_Y;
      let targetTiltX = DEFAULT_TILT_X;
      let targetTiltY = DEFAULT_TILT_Y;
      const TILT_LERP = 0.06;

      // Generate sphere particles on latitude rings
      function initGlobe() {
        particles.length = 0;
        for (let i = 0; i < NUM_RINGS; i++) {
          const theta = Math.PI * (0.06 + 0.88 * (i / (NUM_RINGS - 1)));
          const ringRadius = Math.sin(theta);
          const y = Math.cos(theta);
          const numParticles = Math.max(6, Math.round(MAX_PARTICLES_PER_RING * ringRadius));
          for (let j = 0; j < numParticles; j++) {
            const phi = (2 * Math.PI * j) / numParticles;
            particles.push({
              x: ringRadius * Math.sin(phi),
              y: y,
              z: ringRadius * Math.cos(phi)
            });
          }
        }
      }
      initGlobe();

      // Track mouse over the hero section
      hero.addEventListener('mousemove', function (e) {
        const rect = hero.getBoundingClientRect();
        mouseX = e.clientX - rect.left;
        mouseY = e.clientY - rect.top;
        if (!mouseActive) {
          smoothMouseX = mouseX;
          smoothMouseY = mouseY;
          mouseActive = true;
        }
        // Tilt globe based on cursor position
        const normX = (mouseX / width) - 0.5;
        const normY = (mouseY / height) - 0.5;
        targetTiltX = DEFAULT_TILT_X + normY * 0.8;
        targetTiltY = DEFAULT_TILT_Y + normX * 0.8;
      });

      hero.addEventListener('mouseleave', function () {
        mouseActive = false;
        targetTiltX = DEFAULT_TILT_X;
        targetTiltY = DEFAULT_TILT_Y;
      });

      // Touch events for mobile
      function handleTouch(e) {
        if (e.touches.length > 0) {
          const rect = hero.getBoundingClientRect();
          mouseX = e.touches[0].clientX - rect.left;
          mouseY = e.touches[0].clientY - rect.top;
          if (!mouseActive) {
            smoothMouseX = mouseX;
            smoothMouseY = mouseY;
            mouseActive = true;
          }
          const normX = (mouseX / width) - 0.5;
          const normY = (mouseY / height) - 0.5;
          targetTiltX = DEFAULT_TILT_X + normY * 0.8;
          targetTiltY = DEFAULT_TILT_Y + normX * 0.8;
        }
      }
      hero.addEventListener('touchstart', handleTouch, { passive: true });
      hero.addEventListener('touchmove', handleTouch, { passive: true });
      hero.addEventListener('touchend', function () {
        if (window.innerWidth > 768) {
          mouseActive = false;
        }
        targetTiltX = DEFAULT_TILT_X;
        targetTiltY = DEFAULT_TILT_Y;
      });

      // Helpers
      function lerp(a, b, t) { return (1 - t) * a + t * b; }

      // Color mapping — viewport-stable gradient
      function getColor(nx, ny) {
        let h, s, l;
        if (ny < 0) {
          const t = ny + 1;
          h = lerp(195, 275, t);
          s = lerp(90, 85, t);
          l = lerp(55, 60, t);
        } else {
          const tX = (nx + 1) / 2;
          const botH = lerp(388, 260, tX);
          const botS = lerp(95, 65, tX);
          const botL = lerp(55, 50, tX);
          h = lerp(275, botH, ny);
          s = lerp(85, botS, ny);
          l = lerp(60, botL, ny);
        }
        return { h: h % 360, s: s, l: l };
      }

      // Main draw loop
      function draw() {
        ctx.clearRect(0, 0, width, height);

        // Smooth tilt
        currentTiltX += (targetTiltX - currentTiltX) * TILT_LERP;
        currentTiltY += (targetTiltY - currentTiltY) * TILT_LERP;

        // Smooth spotlight position
        if (mouseActive) {
          smoothMouseX = lerp(smoothMouseX, mouseX, MOUSE_LERP);
          smoothMouseY = lerp(smoothMouseY, mouseY, MOUSE_LERP);
        }

        angleY += spinSpeed;

        // Globe centered in the hero section
        const centerX = width * 0.5;
        const centerY = height * 0.5;
        const sphereRadius = Math.max(180, Math.min(width * 0.35, height * 0.38, 340));

        const cosY = Math.cos(angleY + currentTiltY);
        const sinY = Math.sin(angleY + currentTiltY);
        const cosX = Math.cos(currentTiltX);
        const sinX = Math.sin(currentTiltX);

        // Project all particles
        const projected = [];
        for (let i = 0; i < particles.length; i++) {
          const p = particles[i];
          const rx1 = p.x * cosY - p.z * sinY;
          const rz1 = p.x * sinY + p.z * cosY;
          const ry2 = p.y * cosX - rz1 * sinX;
          const rz2 = p.y * sinX + rz1 * cosX;
          const scale = FOCAL_LENGTH / (FOCAL_LENGTH + rz2 * sphereRadius);
          projected.push({
            px: centerX + rx1 * sphereRadius * scale,
            py: centerY + ry2 * sphereRadius * scale,
            scale: scale,
            rz: rz2,
            rx: rx1,
            ry: ry2
          });
        }

        // Painter's algorithm
        projected.sort((a, b) => b.rz - a.rz);

        // Draw particles (Medical Crosses in Greenish #0a6b5e color)
        for (let i = 0; i < projected.length; i++) {
          const p = projected[i];
          const depth = (p.rz + 1) / 2;
          const baseAlpha = lerp(0.92, 0.2, depth);

          // Medical cross size calculation
          const r = Math.max(2.5, (1.2 + (1 - depth) * 1.0) * p.scale);
          const w = r / 3;

          // Draw 12-point medical cross path to avoid double-transparency overlaps
          ctx.beginPath();
          ctx.moveTo(p.px - r, p.py - w);
          ctx.lineTo(p.px - w, p.py - w);
          ctx.lineTo(p.px - w, p.py - r);
          ctx.lineTo(p.px + w, p.py - r);
          ctx.lineTo(p.px + w, p.py - w);
          ctx.lineTo(p.px + r, p.py - w);
          ctx.lineTo(p.px + r, p.py + w);
          ctx.lineTo(p.px + w, p.py + w);
          ctx.lineTo(p.px + w, p.py + r);
          ctx.lineTo(p.px - w, p.py + r);
          ctx.lineTo(p.px - w, p.py + w);
          ctx.lineTo(p.px - r, p.py + w);
          ctx.closePath();

          ctx.fillStyle = `rgba(10, 107, 94, ${baseAlpha})`;
          ctx.fill();
        }

        // ── MOUSE SPOTLIGHT MASK ──
        const isMobile = window.innerWidth <= 768;
        const isActive = mouseActive || isMobile;

        if (isActive) {
          ctx.save();
          ctx.globalCompositeOperation = 'destination-in';
          
          let smX = smoothMouseX;
          let smY = smoothMouseY;
          
          if (isMobile && !mouseActive) {
            smX = width / 2;
            smY = height / 2;
          }

          const currentRadius = isMobile ? Math.max(REVEAL_RADIUS, width * 0.6) : REVEAL_RADIUS;

          const grad = ctx.createRadialGradient(
            smX, smY, 0,
            smX, smY, currentRadius
          );
          grad.addColorStop(0, 'rgba(255,255,255,1)');
          grad.addColorStop(0.5, 'rgba(255,255,255,0.75)');
          grad.addColorStop(0.8, 'rgba(255,255,255,0.25)');
          grad.addColorStop(1, 'rgba(255,255,255,0)');
          ctx.fillStyle = grad;
          ctx.fillRect(0, 0, width, height);
          ctx.restore();
        } else {
          // Mouse not in hero — hide all particles
          ctx.clearRect(0, 0, width, height);
        }

        requestAnimationFrame(draw);
      }

      draw();
    })();

    /* ============================================================
       FAQ ACCORDION
       ============================================================ */
    (function () {
      const items = document.querySelectorAll('.faq-item');
      items.forEach(function (item) {
        const trigger = item.querySelector('.faq-trigger');
        const panel = item.querySelector('.faq-panel');
        const icon = item.querySelector('.faq-icon-box');

        trigger.addEventListener('click', function () {
          const isActive = item.classList.contains('active');

          // Close other items
          items.forEach(function (otherItem) {
            if (otherItem !== item) {
              otherItem.classList.remove('active');
              otherItem.querySelector('.faq-panel').style.maxHeight = '0px';
              otherItem.querySelector('.faq-trigger').setAttribute('aria-expanded', 'false');
              otherItem.querySelector('.faq-icon-box').textContent = '+';
            }
          });

          // Toggle current item
          if (isActive) {
            item.classList.remove('active');
            panel.style.maxHeight = '0px';
            trigger.setAttribute('aria-expanded', 'false');
            icon.textContent = '+';
          } else {
            item.classList.add('active');
            panel.style.maxHeight = panel.scrollHeight + 'px';
            trigger.setAttribute('aria-expanded', 'true');
            icon.textContent = '−';
          }
        });
      });
    })();

    /* ============================================================
       BLOGS & INSIGHTS (Filtering and Modal)
       ============================================================ */
    (function () {
      // Card filtering logic
      const filters = document.querySelectorAll('.blog-filters .filter-btn');
      const cards = document.querySelectorAll('.blog-grid .blog-card');

      filters.forEach(btn => {
        btn.addEventListener('click', function () {
          // Remove active class from all filter buttons
          filters.forEach(f => f.classList.remove('active'));
          // Add active class to clicked button
          this.classList.add('active');

          const filterVal = this.dataset.filter;

          cards.forEach(card => {
            if (filterVal === 'all' || card.dataset.category === filterVal) {
              card.style.display = 'flex';
              // Trigger simple fade/slide animation
              card.style.animation = 'fadeIn 0.4s ease forwards';
            } else {
              card.style.display = 'none';
            }
          });

          // Track GA event
          if (typeof gtag === 'function') {
            gtag('event', 'filter_blogs', { 'category': filterVal });
          }
        });
      });
    })();

    /* ============================================================
       BORDER GLOW CARD INTEGRATION
       ============================================================ */
    (function () {
      function parseHSL(hslStr) {
        const match = hslStr.match(/([\d.]+)\s*([\d.]+)%?\s*([\d.]+)%?/);
        if (!match) return { h: 40, s: 80, l: 80 };
        return { h: parseFloat(match[1]), s: parseFloat(match[2]), l: parseFloat(match[3]) };
      }

      function buildGlowVars(glowColor, intensity) {
        const parsed = parseHSL(glowColor);
        const h = parsed.h, s = parsed.s, l = parsed.l;
        const base = `${h}deg ${s}% ${l}%`;
        const opacities = [100, 60, 50, 40, 30, 20, 10];
        const keys = ['', '-60', '-50', '-40', '-30', '-20', '-10'];
        const vars = {};
        for (let i = 0; i < opacities.length; i++) {
          vars[`--glow-color${keys[i]}`] = `hsl(${base} / ${Math.min(opacities[i] * intensity, 100)}%)`;
        }
        return vars;
      }

      const GRADIENT_POSITIONS = ['80% 55%', '69% 34%', '8% 6%', '41% 38%', '86% 85%', '82% 18%', '51% 4%'];
      const GRADIENT_KEYS = ['--gradient-one', '--gradient-two', '--gradient-three', '--gradient-four', '--gradient-five', '--gradient-six', '--gradient-seven'];
      const COLOR_MAP = [0, 1, 2, 0, 1, 2, 1];

      function buildGradientVars(colors) {
        const vars = {};
        for (let i = 0; i < 7; i++) {
          const c = colors[Math.min(COLOR_MAP[i], colors.length - 1)];
          vars[GRADIENT_KEYS[i]] = `radial-gradient(at ${GRADIENT_POSITIONS[i]}, ${c} 0px, transparent 50%)`;
        }
        vars['--gradient-base'] = `linear-gradient(${colors[0]} 0 100%)`;
        return vars;
      }

      function easeOutCubic(x) { return 1 - Math.pow(1 - x, 3); }
      function easeInCubic(x) { return x * x * x; }

      function animateProp(card, duration, start, end, ease, onUpdate, onEnd) {
        const startTime = performance.now();
        function tick(now) {
          const elapsed = now - startTime;
          const progress = Math.min(elapsed / duration, 1);
          const val = start + (end - start) * ease(progress);
          onUpdate(val);
          if (progress < 1) {
            requestAnimationFrame(tick);
          } else if (onEnd) {
            onEnd();
          }
        }
        requestAnimationFrame(tick);
      }

      function runSweepAnimation(card) {
        const angleStart = 110;
        const angleEnd = 465;
        card.classList.add('sweep-active');
        card.style.setProperty('--cursor-angle', angleStart + 'deg');

        animateProp(card, 500, 0, 100, easeOutCubic, function (v) {
          card.style.setProperty('--edge-proximity', v.toFixed(3));
        });

        animateProp(card, 1500, 0, 50, easeInCubic, function (v) {
          const angle = (angleEnd - angleStart) * (v / 100) + angleStart;
          card.style.setProperty('--cursor-angle', angle.toFixed(3) + 'deg');
        });

        setTimeout(function () {
          animateProp(card, 2250, 50, 100, easeOutCubic, function (v) {
            const angle = (angleEnd - angleStart) * (v / 100) + angleStart;
            card.style.setProperty('--cursor-angle', angle.toFixed(3) + 'deg');
          });
        }, 1500);

        setTimeout(function () {
          animateProp(card, 1500, 100, 0, easeInCubic, function (v) {
            card.style.setProperty('--edge-proximity', v.toFixed(3));
          }, function () {
            card.classList.remove('sweep-active');
          });
        }, 2500);
      }

      function initBorderGlow(card, options) {
        const defaults = {
          edgeSensitivity: 30,
          glowColor: '173 84 50', // Teal tone matching page
          backgroundColor: '#0e1514', // Deep dark backdrop to highlight the glows
          borderRadius: 24,
          glowRadius: 40,
          glowIntensity: 1.0,
          coneSpread: 25,
          animated: true, // sweep on load
          colors: ['#0c8a7b', '#c084fc', '#38bdf8'], // theme teal + accent violet + accent blue
          fillOpacity: 0.5
        };
        const settings = Object.assign({}, defaults, options);

        card.style.setProperty('--card-bg', settings.backgroundColor);
        card.style.setProperty('--edge-sensitivity', settings.edgeSensitivity);
        card.style.setProperty('--border-radius', settings.borderRadius + 'px');
        card.style.setProperty('--glow-padding', settings.glowRadius + 'px');
        card.style.setProperty('--cone-spread', settings.coneSpread);
        card.style.setProperty('--fill-opacity', settings.fillOpacity);

        const glowVars = buildGlowVars(settings.glowColor, settings.glowIntensity);
        for (const key in glowVars) {
          card.style.setProperty(key, glowVars[key]);
        }

        const gradientVars = buildGradientVars(settings.colors);
        for (const key in gradientVars) {
          card.style.setProperty(key, gradientVars[key]);
        }

        // Pointer move event listener
        card.addEventListener('pointermove', function (e) {
          const rect = card.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;

          const cx = rect.width / 2;
          const cy = rect.height / 2;

          const dx = x - cx;
          const dy = y - cy;

          let kx = Infinity;
          let ky = Infinity;
          if (dx !== 0) kx = cx / Math.abs(dx);
          if (dy !== 0) ky = cy / Math.abs(dy);
          const edge = Math.min(Math.max(1 / Math.min(kx, ky), 0), 1);

          let angle = 0;
          if (dx !== 0 || dy !== 0) {
            const radians = Math.atan2(dy, dx);
            angle = radians * (180 / Math.PI) + 90;
            if (angle < 0) angle += 360;
          }

          card.style.setProperty('--edge-proximity', (edge * 100).toFixed(3));
          card.style.setProperty('--cursor-angle', angle.toFixed(3) + 'deg');
        });

        if (settings.animated) {
          setTimeout(function () {
            runSweepAnimation(card);
          }, 800);
        }
      }

      // Initialize all cards with class border-glow-card
      window.addEventListener('DOMContentLoaded', function () {
        document.querySelectorAll('.border-glow-card').forEach(function (card) {
          initBorderGlow(card);
        });
      });
    })();


  